I have a question about attachments. I have seen all of your replies so trust me I have spent a full day on this problem but still can't get my head around. The way I have setup is that I download emails but not attachments, instead just save their names and disposition. Then when customer open the email, he can see the list of attachments and just click on them to download, however they are downloading as corrupted. Here is the download code.

``` csharp
        public MemoryStream GetAttachement(string fileName, string messageId)
        {
            HeaderSearchQuery searchCondition = SearchQuery.HeaderContains("Message-Id", messageId);
            Client.Inbox.Open(FolderAccess.ReadOnly);
            IList<UniqueId> uids = Client.Inbox.Search(searchCondition);

            foreach (UniqueId uniqueId in uids)
            {
                MimeMessage message = Client.Inbox.GetMessage(uniqueId);
                if (message.Attachments.Count() > 0)
                {
                    var attachement = message.Attachments.Where(x => x.ContentDisposition.FileName.Equals(fileName, StringComparison.InvariantCultureIgnoreCase)).FirstOrDefault();
                    if (attachement != null)
                    {
                        var stream = new MemoryStream();
                        attachement.WriteTo(stream);
                        attachement.WriteTo(System.Web.HttpContext.Current.Server.MapPath("~/") + fileName);
                        return stream;
                    }
                }
                //check for inline attachements
                var inlineattachement = message.BodyParts.Where(x => x.ContentType.MediaType.Equals("image", StringComparison.InvariantCultureIgnoreCase) && x.ContentType.Name.Equals(fileName, StringComparison.InvariantCultureIgnoreCase)).FirstOrDefault();
                if (inlineattachement != null)
                {
                    var stream = new MemoryStream();
                    inlineattachement.WriteTo(stream);
                    inlineattachement.WriteTo(System.Web.HttpContext.Current.Server.MapPath("~/") + fileName);
                    return stream;
                }
            }

            return null;
        }
```

As a test, I am writing to both stream and saving to file but nothing is working. I have the latest version, so any help will be greatly appreciated.
Thanks in advance.

comments.body:
You are writing out the MIME container of the attachment and not the decoded attachment data.

What you need to do is this:

``` csharp
var stream = new MemoryStream();
if (attachment is MessagePart) {
    var rfc822 = (MessagePart) attachment;
    rfc822.Message.WriteTo (stream);
    rfc822.Message.WriteTo (System.Web.HttpContext.Current.Server.MapPath("~/") + fileName);
} else {
    var part = (MimePart) attachment;
    part.ContentObject.DecodeTo (stream);
    part.ContentObject.DecodeTo (System.Web.HttpContext.Current.Server.MapPath("~/") + fileName);
}
return stream;
```

(Note: For the inlineattachment logic, you don't need to check for `MessagePart` because that can't happen, image parts can only ever be `MimePart`s)

